mod.js:
let items=[],shown=[],act=0;
const list=morse.el('div',{class:'mj-list'});
const input=morse.el('input',{type:'text',autocomplete:'off','aria-label':'Filter identifiers'});
const dlg=morse.el('dialog',{id:'morse-jump','aria-label':'Jump to identifier'},
  morse.el('div',{class:'mj-title'},morse.el('h2',{text:'Jump to'}),
    morse.el('button',{class:'mj-x',type:'button','aria-label':'Close',text:'×',on:{click:()=>dlg.close()}})),
  input,list,
  morse.el('div',{class:'mj-actions'},morse.el('button',{class:'mj-close',type:'button',text:'Close',on:{click:()=>dlg.close()}})));
document.body.append(dlg);
const esc=s=>s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function go(h){dlg.close();const t=document.getElementById(decodeURIComponent(h.slice(1)));if(t){t.scrollIntoView();history.replaceState(null,'',h);}else location.hash=h;}
function render(){
  const q=input.value.trim().toLowerCase();list.textContent='';
  shown=items.filter(i=>!q||i.t.toLowerCase().includes(q)).slice(0,200);
  act=0;
  shown.forEach((i,n)=>{let html=esc(i.t);
    if(q){const k=i.t.toLowerCase().indexOf(q);html=esc(i.t.slice(0,k))+'<b>'+esc(i.t.slice(k,k+q.length))+'</b>'+esc(i.t.slice(k+q.length));}
    list.append(morse.el('a',{href:i.h,tabindex:'-1',html,class:n?'':'mj-active',on:{click:e=>{e.preventDefault();go(i.h);}}}));});
}
function mark(){[...list.children].forEach((a,n)=>a.classList.toggle('mj-active',n===act));list.children[act]?.scrollIntoView({block:'nearest'});}
morse.on(input,'input',render);
morse.on(input,'keydown',e=>{
  if(e.key==='ArrowDown'){act=Math.min(act+1,shown.length-1);mark();e.preventDefault();}
  else if(e.key==='ArrowUp'){act=Math.max(act-1,0);mark();e.preventDefault();}
  else if(e.key==='Enter'&&shown[act]){e.preventDefault();go(shown[act].h);}
});
morse.on(dlg,'click',e=>{if(e.target===dlg)dlg.close();});
function collect(){
  const seen=new Set(),out=[];
  const add=(t,h)=>{t=(t||'').replace(/#\s*$/,'').trim();if(t&&h&&h.length>1&&!seen.has(h)){seen.add(h);out.push({t,h});}};
  morse.$$('#apicontent section h2, #apicontent section h3, #apicontent section h4, #apicontent section h5').forEach(hd=>{
    const a=hd.querySelector('a[href*="#"]');
    const id=hd.id||(a&&a.getAttribute('href').split('#')[1]);
    add(hd.textContent,id?'#'+id:'');
  });
  morse.$$('details#toc a[href*="#"]').forEach(a=>{const h=a.getAttribute('href');add(a.textContent,h.slice(h.indexOf('#')));});
  return out;
}
function open(){items=collect();input.value='';render();if(!dlg.open)dlg.showModal();input.focus();}
morse.on(document,'keydown',e=>{
  if((e.key==='f'||e.key==='F')&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!dlg.open&&!e.target.closest('input,textarea,select,[contenteditable]')){e.preventDefault();open();}
});
morse.watch('#gtoc > ul',ul=>{
  ul.append(morse.el('li',{class:'picker-header mj-btn'},morse.el('a',{href:'#',title:'Jump to identifier (F)',text:'Jump to…',on:{click:e=>{e.preventDefault();open();}}})));
});

